import Anthropic from "@anthropic-ai/sdk";
import { betaZodOutputFormat } from "@anthropic-ai/sdk/helpers/beta/zod";
import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import { z } from "zod";
import type { TrialDetail } from "./types";

/**
 * Plain-language Thai explanation of a trial, generated by Claude and cached
 * on disk per study + last-update date (so it regenerates when the record changes).
 */

export const PlainThaiSchema = z.object({
  title_th: z.string().describe("ชื่องานวิจัยแปลเป็นภาษาไทยที่เข้าใจง่าย ไม่เกิน 1 บรรทัด"),
  summary_th: z.string().describe("งานวิจัยนี้ศึกษาอะไร ทำไม และใครควรสนใจ 2-4 ประโยค ภาษาชาวบ้าน"),
  what_you_do_th: z
    .string()
    .describe("ถ้าเข้าร่วมจะต้องทำอะไรบ้าง เช่น รับยา มาตรวจกี่ครั้ง ระยะเวลา (ถ้าข้อมูลไม่บอก ให้บอกว่าไม่ระบุ)"),
  inclusion_th: z.array(z.string()).describe("เกณฑ์คัดเข้า แต่ละข้อเป็นภาษาไทยง่ายๆ เรียงตามต้นฉบับ"),
  exclusion_th: z.array(z.string()).describe("เกณฑ์คัดออก แต่ละข้อเป็นภาษาไทยง่ายๆ เรียงตามต้นฉบับ"),
  questions_th: z.array(z.string()).describe("คำถาม 3-5 ข้อที่อาสาสมัครควรถามทีมวิจัยก่อนตัดสินใจ เฉพาะกับงานวิจัยนี้"),
});

export type PlainThai = z.infer<typeof PlainThaiSchema>;

const SYSTEM = `คุณเป็นผู้ช่วยที่อธิบายงานวิจัยทางคลินิกให้คนไทยทั่วไปเข้าใจ
- เขียนภาษาไทยระดับที่คนจบมัธยมอ่านเข้าใจ เลี่ยงศัพท์แพทย์ ถ้าจำเป็นให้วงเล็บอธิบาย เช่น "ค่าน้ำตาลสะสม (HbA1c)"
- แปลให้ตรงความหมายต้นฉบับ ห้ามเพิ่มเกณฑ์ ตัวเลข หรือข้อมูลที่ต้นฉบับไม่มี ตัวเลขและหน่วยต้องคงเดิม
- ห้ามชักชวน ห้ามสัญญาว่าจะได้ประโยชน์หรือหายจากโรค และห้ามให้คำแนะนำทางการแพทย์เฉพาะบุคคล
- ถ้าต้นฉบับไม่มีข้อมูลส่วนใด ให้ระบุว่า "ต้นฉบับไม่ได้ระบุ" แทนการเดา`;

const MODEL = process.env.CLAUDE_MODEL || "claude-opus-5-5";
const CACHE_DIR = process.env.VERCEL ? path.join(os.tmpdir(), "clinicalthai-ai") : path.join(process.cwd(), ".cache", "ai");

export function aiEnabled() {
  return Boolean(process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_AUTH_TOKEN);
}

let client: Anthropic | null = null;

function cacheFile(t: TrialDetail) {
  return path.join(CACHE_DIR, `${t.id}_${t.lastUpdated ?? "na"}.json`);
}

export async function getCachedPlainThai(t: TrialDetail): Promise<PlainThai | null> {
  try {
    return PlainThaiSchema.parse(JSON.parse(await fs.readFile(cacheFile(t), "utf8")));
  } catch {
    return null;
  }
}

function buildPrompt(t: TrialDetail): string {
  const parts = [
    `ชื่อ: ${t.title}`,
    t.officialTitle && t.officialTitle !== t.title ? `ชื่อทางการ: ${t.officialTitle}` : "",
    `ประเภท: ${t.studyType}${t.phases.length ? ` (${t.phases.join(", ")})` : ""}`,
    `โรค/ภาวะ: ${t.conditions.join(", ")}`,
    t.interventions.length ? `สิ่งที่ทดสอบ: ${t.interventions.map((i) => `${i.type}: ${i.name}`).join("; ")}` : "",
    t.arms.length
      ? `กลุ่มการศึกษา:\n${t.arms.map((a) => `- ${a.label}${a.description ? `: ${a.description}` : ""}`).join("\n")}`
      : "",
    t.primaryOutcomes.length
      ? `ผลลัพธ์หลัก:\n${t.primaryOutcomes.map((o) => `- ${o.measure}${o.timeFrame ? ` (${o.timeFrame})` : ""}`).join("\n")}`
      : "",
    `สรุปย่อ:\n${t.summary ?? "-"}`,
    t.detailedDescription ? `รายละเอียด:\n${t.detailedDescription}` : "",
    `เกณฑ์การคัดเลือก (ต้นฉบับ):\n${t.eligibilityCriteria ?? "-"}`,
  ];
  return `อธิบายงานวิจัยต่อไปนี้เป็นภาษาไทยง่ายๆ สำหรับผู้ที่สนใจเป็นอาสาสมัคร\n\n<study>\n${parts
    .filter(Boolean)
    .join("\n\n")}\n</study>`;
}

export class AiRefusalError extends Error {}

export async function generatePlainThai(t: TrialDetail): Promise<PlainThai> {
  const cached = await getCachedPlainThai(t);
  if (cached) return cached;
  client ??= new Anthropic();

  const response = await client.beta.messages.parse({
    model: MODEL,
    max_tokens: 16000,
    betas: ["server-side-fallback-2026-07-01"],
    fallbacks: "default",
    system: SYSTEM,
    output_config: { effort: "low", format: betaZodOutputFormat(PlainThaiSchema) },
    messages: [{ role: "user", content: buildPrompt(t) }],
  });

  if (response.stop_reason === "refusal") throw new AiRefusalError("model declined");
  if (response.stop_reason === "max_tokens" || !response.parsed_output) {
    throw new Error(`incomplete AI response (${response.stop_reason})`);
  }
  const out = response.parsed_output;
  try {
    await fs.mkdir(CACHE_DIR, { recursive: true });
    await fs.writeFile(cacheFile(t), JSON.stringify(out));
  } catch {
    // read-only filesystem — skip disk cache
  }
  return out;
}
